"""A small LRU cache with key helpers and a shared default instance."""

from collections import OrderedDict
from typing import Any, Hashable, Optional

_SEPARATOR = "\x1f"
_DEFAULT_CAPACITY = 128
_default: Optional["LRUCache"] = None


def make_key(*parts: Any) -> str:
    """Join parts into a single string key."""
    return _SEPARATOR.join(str(part) for part in parts)


def normalize_key(key: Any) -> Hashable:
    """Return a canonical hashable form of a key."""
    if isinstance(key, str):
        return key.strip().lower()
    if isinstance(key, (tuple, list)):
        return make_key(*(normalize_key(part) for part in key))
    return key


class LRUCache:
    """Least-recently-used cache with a fixed capacity."""

    def __init__(self, capacity: int = _DEFAULT_CAPACITY) -> None:
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._data: "OrderedDict[Hashable, Any]" = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0

    def get(self, key: Any, default: Any = None) -> Any:
        k = normalize_key(key)
        if k not in self._data:
            self._misses += 1
            return default
        self._data.move_to_end(k)
        self._hits += 1
        return self._data[k]

    def put(self, key: Any, value: Any) -> None:
        k = normalize_key(key)
        self._data[k] = value
        self._data.move_to_end(k)
        while len(self._data) > self.capacity:
            self.evict()

    def evict(self) -> Optional[Hashable]:
        """Drop the least recently used entry and return its key."""
        if not self._data:
            return None
        k, _ = self._data.popitem(last=False)
        self._evictions += 1
        return k

    def stats(self) -> dict:
        return {
            "size": len(self._data),
            "capacity": self.capacity,
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
        }


def default_cache() -> LRUCache:
    """Return the shared module-level cache, creating it on first use."""
    global _default
    if _default is None:
        _default = LRUCache()
    return _default
